import {pool,makeState,box,active,concentration,physicsFor,updateParents} from './measurement-common.js';
export * from './measurement-common.js';
// Illustrative Cu(II) response, not a measured spectrum or calibrated instrument.
export const FILTERS={red:{name:'Red · 635 nm',epsilon:20},green:{name:'Green · 525 nm',epsilon:5},blue:{name:'Blue · 470 nm',epsilon:1.5}};
export function createState(){const items={stock:pool('stock','CuSO₄ stock · 0.100 M',140,429,100,{Cu:.01,sulfate:.01}),water:pool('water','Deionised water',270,429,500,{},600),standard1:pool('standard1','Standard 1',400,429),standard2:pool('standard2','Standard 2',520,429),standard3:pool('standard3','Standard 3',640,429),standard4:pool('standard4','Standard 4',190,100),unknown:pool('unknown','Unknown CuSO₄',290,100,50,{Cu:.00175,sulfate:.00175}),waste:pool('waste','Waste beaker',390,100,0,{},1000),
 meter:{id:'meter',name:'Colorimeter',kind:'colorimeter',x:820,y:435,angle:0,lid:false,collision:[box(0,45,185,90)],mass:4},
 cuvetteA:{...pool('cuvetteA','Cuvette A',490,100,0,{},4),kind:'cuvette',clean:false,clearFace:true,collision:[box(-12,30,3,60),box(12,30,3,60),box(0,58,27,4)]},cuvetteB:{...pool('cuvetteB','Cuvette B',590,100,0,{},4),kind:'cuvette',clean:false,clearFace:true,collision:[box(-12,30,3,60),box(12,30,3,60),box(0,58,27,4)]}};
 const s=makeState('colorimetry',items);Object.assign(s,{filter:'red',blank:null,unknownReadings:[]});return s;}
export const seated=s=>Object.values(s.items).find(o=>active(o)&&o.kind==='cuvette'&&o.parent==='meter');
export function insert(s,id){const o=s.items[id],m=s.items.meter;if(s.phase!=='working'||!active(o)||o.kind!=='cuvette'||!active(m)||m.lid||seated(s)||Math.abs(o.x-m.x)>155||Math.abs(o.y-m.y)>140)return false;o.parent='meter';o.offset={x:48,y:-10};updateParents(s);physicsFor(s).sync();return true;}
export function remove(s){const o=seated(s);if(s.phase!=='working'||!o||s.items.meter.lid)return false;o.parent=null;o.y-=90;physicsFor(s).sync();return true;}
export function transmission(s){const c=seated(s),m=s.items.meter;if(!active(m)||!c)return{value:null,status:'Insert a cuvette.'};if(c.water<2)return{value:null,status:'Liquid is below the light beam. Add at least 2 mL.'};const absorbance=FILTERS[s.filter].epsilon*concentration(c,'Cu')+(c.clean?0:.06)+(c.clearFace?0:.25),stray=.003+(m.lid?0:.07),value=(10**(-absorbance)+stray)/(1+stray);return{value,status:m.lid?'Lid closed.':'Lid open · stray light affects the measurement.',cuvette:c.id};}
export function blank(s){if(s.phase!=='working')return false;const r=transmission(s);if(r.value===null)return false;s.blank={transmission:r.value,filter:s.filter,cuvette:r.cuvette,volume:s.items[r.cuvette].water,time:s.time};return true;}
export function reading(s){const r=transmission(s);if(r.value===null)return r;if(!s.blank)return{...r,value:null,status:'Set the blank before measuring absorbance.'};const value=-Math.log10(r.value/s.blank.transmission);return{...r,value,filter:s.filter,status:r.status+(s.blank.filter!==s.filter?' Filter changed since blanking.':'')+(value>1.2?' High absorbance · interpolation may be unreliable.':'')};}
export function record(s,type,known,label=''){if(s.phase!=='working'||!['standard','unknown'].includes(type))return null;const r=reading(s);if(r.value===null||!Number.isFinite(r.value)||type==='standard'&&(known===''||known===null||!Number.isFinite(Number(known))||Number(known)<0))return null;const row={type,label:String(label).slice(0,60)|| (type==='standard'?'Standard':'Unknown'),concentration:type==='standard'?Number(known):null,absorbance:Number(r.value.toFixed(3)),filter:s.filter,blankFilter:s.blank.filter,clean:seated(s).clean,clearFace:seated(s).clearFace,lid:s.items.meter.lid,volume:seated(s).water,time:s.time};(type==='standard'?s.records:s.unknownReadings).push(row);return row;}
export function fitCalibration(rows,filter){const points=rows.filter(r=>r.type==='standard'&&r.filter===filter);if(points.length<3||new Set(points.map(r=>r.concentration)).size<3)return null;const n=points.length,x=points.reduce((v,r)=>v+r.concentration,0)/n,y=points.reduce((v,r)=>v+r.absorbance,0)/n,xx=points.reduce((v,r)=>v+(r.concentration-x)**2,0);if(xx<1e-15)return null;const slope=points.reduce((v,r)=>v+(r.concentration-x)*(r.absorbance-y),0)/xx,intercept=y-slope*x,ss=points.reduce((v,r)=>v+(r.absorbance-y)**2,0),res=points.reduce((v,r)=>v+(r.absorbance-slope*r.concentration-intercept)**2,0);if(!Number.isFinite(slope)||Math.abs(slope)<1e-9)return null;return{slope,intercept,r2:ss<1e-15?0:1-res/ss,min:Math.min(...points.map(r=>r.concentration)),max:Math.max(...points.map(r=>r.concentration)),n};}
export function estimate(s,row=s.unknownReadings.at(-1)){if(!row)return null;const fit=fitCalibration(s.records,row.filter);if(!fit)return null;const value=(row.absorbance-fit.intercept)/fit.slope;return{value,fit,extrapolated:value<fit.min||value>fit.max};}
export function stepChemistry(s,dt){if(s.phase==='working'&&Number.isFinite(dt)&&dt>0)s.time+=dt;}
